import AIInstructions
import FoundationModels
import GitHub

/// A pull request title and description, generated by the on-device model.
@Generable
struct PullRequestDraft {
    @Guide(description: "One line under 72 characters, imperative mood, no trailing period")
    var title: String
    @Guide(description: "GitHub Markdown: what was wrong or missing and why, then how the change addresses it")
    var body: String
}

/// Drafts pull requests with Apple's on-device model: private, free and offline, when the Mac has
/// Apple Intelligence.
enum PullRequestDrafter {
    /// Why drafting isn't possible on this Mac right now, or `nil` when it is.
    static var unavailableReason: String? {
        switch SystemLanguageModel.default.availability {
        case .available:
            nil
        case .unavailable(.deviceNotEligible):
            "This Mac doesn't support Apple Intelligence."
        case .unavailable(.appleIntelligenceNotEnabled):
            "Turn on Apple Intelligence in System Settings to draft with AI."
        case .unavailable(.modelNotReady):
            "Apple Intelligence is still downloading."
        case .unavailable:
            "Apple Intelligence isn't available."
        }
    }

    /// Streams the draft into `update` as it's written: title first, then the description. The
    /// user's `instructions` for pull requests come after Native's own.
    static func draft(
        _ prompt: PullRequestDraftPrompt, instructions addition: AIInstructionAddition? = nil,
        update: (_ title: String?, _ body: String?) -> Void
    ) async throws {
        let model = SystemLanguageModel.default
        // About 2.5 characters per token for code, leaving room for the instructions and the answer.
        var budget = max(Int(Double(model.contextSize - 1_500) * 2.5), 2_000)
        for attempt in 0..<2 {
            let session = LanguageModelSession(
                model: model, instructions: PullRequestDraftPrompt.instructions(adding: addition))
            do {
                let stream = session.streamResponse(
                    to: prompt.text(characterBudget: budget), generating: PullRequestDraft.self)
                for try await snapshot in stream {
                    update(snapshot.content.title, snapshot.content.body)
                }
                return
            } catch LanguageModelError.contextSizeExceeded(_) where attempt == 0 {
                // The estimate was off for this material; half as much always fits.
                budget /= 2
            }
        }
    }
}
